 glossary=[G("Operator", "A mapping from one function to another, such as from a PDE's source to its solution."), G("DeepONet", "A neural operator with a branch network for the input function and a trunk network for the query location."), G("Fourier neural operator", "A neural operator that applies learned filters in Fourier (frequency) space."), G("Solution operator", "The map from a problem's inputs to its solution."), G("Resolution independence", "The ability to evaluate on grids different from those used in training.")],
