 glossary=[G("Hybrid model", "A model combining a physics-based component with a data-driven component."), G("Residual learning", "Learning the error of a physics model and adding it as a correction."), G("Closure term", "A term representing unresolved processes in a coarse model."), G("Gray-box model", "A model mixing known physical structure with learned components."), G("Greenshields model", "A linear speed–density relation for traffic, from 1935.")],
